package pc;

import static org.junit.jupiter.api.Assertions.*;

import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;

class PersistentStackTest {
    @Test
    void emptyStackBasics() {
        PersistentStack<String> s = PersistentStack.empty();
        assertTrue(s.isEmpty());
        assertEquals(0, s.size());
        assertTrue(s.peek().isEmpty());
        assertThrows(IllegalStateException.class, s::pop);
        assertEquals("[]", s.toString());
    }

    @Test
    void pushPeekPopLeaveOldVersionsUntouched() {
        PersistentStack<Integer> a = PersistentStack.<Integer>empty().push(1);
        PersistentStack<Integer> b = a.push(2);
        assertEquals(1, a.size());
        assertEquals(2, b.size());
        assertEquals(2, b.peek().orElseThrow());
        assertEquals(1, a.peek().orElseThrow());
        assertSame(a, b.pop());
    }

    @Test
    void iteratesTopFirstAndStreams() {
        PersistentStack<Integer> s = PersistentStack.<Integer>empty().push(1).push(2).push(3);
        List<Integer> seen = new ArrayList<>();
        for (int x : s) seen.add(x);
        assertEquals(List.of(3, 2, 1), seen);
        assertEquals(List.of(3, 2, 1), s.stream().toList());
        assertEquals("[3, 2, 1]", s.toString());
    }

    @Test
    void equalsAndHashCodeBySequence() {
        PersistentStack<Integer> x = PersistentStack.<Integer>empty().push(1).push(2);
        PersistentStack<Integer> y = PersistentStack.<Integer>empty().push(1).push(2);
        PersistentStack<Integer> z = PersistentStack.<Integer>empty().push(2).push(1);
        assertEquals(x, y);
        assertEquals(x.hashCode(), y.hashCode());
        assertNotEquals(x, z);
        assertNotEquals(x, PersistentStack.<Integer>empty());
        assertEquals(PersistentStack.<Integer>empty(), PersistentStack.<Integer>empty());
    }

    @Test
    void rejectsNull() {
        assertThrows(NullPointerException.class, () -> PersistentStack.<String>empty().push(null));
    }

    @Test
    void largeStackDoesNotOverflow() {
        PersistentStack<Integer> s = PersistentStack.empty();
        for (int i = 0; i < 100_000; i++) s = s.push(i);
        PersistentStack<Integer> t = PersistentStack.empty();
        for (int i = 0; i < 100_000; i++) t = t.push(i);
        assertEquals(100_000, s.size());
        assertEquals(s, t);
        assertEquals(s.hashCode(), t.hashCode());
        assertEquals(99_999, s.peek().orElseThrow());
    }

    @Test
    void iteratorExhaustionThrows() {
        var it = PersistentStack.<Integer>empty().push(1).iterator();
        assertEquals(1, it.next());
        assertFalse(it.hasNext());
        assertThrows(java.util.NoSuchElementException.class, it::next);
    }
}

package pc;

import static org.junit.jupiter.api.Assertions.*;

import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;

class PersistentQueueTest {
    @Test
    void emptyQueue() {
        PersistentQueue<String> q = PersistentQueue.empty();
        assertTrue(q.isEmpty());
        assertTrue(q.peek().isEmpty());
        assertThrows(IllegalStateException.class, q::dequeue);
        assertEquals("[]", q.toString());
    }

    @Test
    void fifoOrder() {
        PersistentQueue<Integer> q = PersistentQueue.<Integer>empty().enqueue(1).enqueue(2).enqueue(3);
        assertEquals(1, q.peek().orElseThrow());
        var d = q.dequeue();
        assertEquals(1, d.head());
        assertEquals(List.of(2, 3), d.rest().stream().toList());
        assertEquals(2, d.rest().size());
    }

    @Test
    void interleavedOperationsKeepOrder() {
        PersistentQueue<Integer> q = PersistentQueue.<Integer>empty().enqueue(1).enqueue(2);
        var d1 = q.dequeue();
        PersistentQueue<Integer> q2 = d1.rest().enqueue(3).enqueue(4);
        var d2 = q2.dequeue();
        assertEquals(2, d2.head());
        assertEquals(List.of(3, 4), d2.rest().stream().toList());
        assertEquals(List.of(1, 2), q.stream().toList(), "original unchanged");
    }

    @Test
    void oldVersionCanBeDequeuedRepeatedly() {
        PersistentQueue<Integer> q = PersistentQueue.<Integer>empty().enqueue(1).enqueue(2);
        assertEquals(1, q.dequeue().head());
        assertEquals(1, q.dequeue().head());
        assertEquals(2, q.size());
    }

    @Test
    void equalsByElementSequenceRegardlessOfInternalSplit() {
        PersistentQueue<Integer> a = PersistentQueue.<Integer>empty().enqueue(1).enqueue(2).enqueue(3);
        PersistentQueue<Integer> b = PersistentQueue.<Integer>empty().enqueue(0).enqueue(1).enqueue(2)
                .dequeue().rest().enqueue(3);
        assertEquals(a, b);
        assertEquals(a.hashCode(), b.hashCode());
        assertNotEquals(a, b.enqueue(4));
    }

    @Test
    void largeQueueDrainsInOrder() {
        PersistentQueue<Integer> q = PersistentQueue.empty();
        for (int i = 0; i < 100_000; i++) q = q.enqueue(i);
        List<Integer> out = new ArrayList<>();
        while (!q.isEmpty()) {
            var d = q.dequeue();
            out.add(d.head());
            q = d.rest();
        }
        assertEquals(100_000, out.size());
        for (int i = 0; i < out.size(); i++) assertEquals(i, out.get(i));
    }

    @Test
    void rejectsNull() {
        assertThrows(NullPointerException.class, () -> PersistentQueue.<String>empty().enqueue(null));
    }
}
